import java.util.*;

class Solution {
  public long countInterestingSubarrays(List<Integer> nums, int modulo, int k) {
    Map<Integer, Long> counts = new HashMap<>();
    counts.put(0, 1L);
    long answer = 0, prefix = 0;
    for (int value : nums) {
      if (value % modulo == k) prefix++;
      int current = (int) (prefix % modulo);
      int needed = (current - k + modulo) % modulo;
      answer += counts.getOrDefault(needed, 0L);
      counts.put(current, counts.getOrDefault(current, 0L) + 1);
    }
    return answer;
  }
}
